import 'dart:convert';
import 'dart:io';
class ApiClient { ApiClient({this.baseUrl='http://localhost:3000/api/v1'}); final String baseUrl; String? accessToken; Future<Map<String,dynamic>> get(String path)=>_send('GET',path); Future<Map<String,dynamic>> post(String path, Map<String,dynamic> body)=>_send('POST',path,body:body); Future<Map<String,dynamic>> _send(String method,String path,{Map<String,dynamic>? body}) async { final client=HttpClient(); final req=await client.openUrl(method,Uri.parse('$baseUrl$path')); req.headers.contentType=ContentType.json; if(accessToken!=null){req.headers.set(HttpHeaders.authorizationHeader,'Bearer $accessToken');} if(body!=null){req.write(jsonEncode(body));} final res=await req.close(); final payload=await res.transform(utf8.decoder).join(); client.close(); if(payload.isEmpty) return {}; return jsonDecode(payload) as Map<String,dynamic>; } }
